{
  "name": "lottie-ios",
  "version": "4.6.0",
  "summary": "A library to render native animations from bodymovin json",
  "description": "Lottie is a mobile library for Android and iOS that parses Adobe After Effects animations exported as json with bodymovin and renders the vector animations natively on mobile and through React Native!\n\nLottie enables designers to create and ship beautiful animations without an engineer painstakingly recreating it be hand. Since the animation is backed by JSON they are extremely small in size but can be large in complexity! Animations can be played, resized, looped, sped up, slowed down, and even interactively scrubbed.",
  "homepage": "https://github.com/airbnb/lottie-ios",
  "license": {
    "type": "Apache",
    "file": "LICENSE"
  },
  "authors": {
    "Brandon Withrow": "buba447@gmail.com",
    "Cal Stephens": "cal.stephens@airbnb.com"
  },
  "source": {
    "git": "https://github.com/airbnb/lottie-ios.git",
    "tag": "4.6.0"
  },
  "swift_versions": "5.9",
  "platforms": {
    "ios": "13.0",
    "osx": "10.15",
    "tvos": "13.0",
    "visionos": "1.0"
  },
  "source_files": "Sources/**/*.swift",
  "resource_bundles": {
    "LottiePrivacyInfo": [
      "Sources/PrivacyInfo.xcprivacy"
    ]
  },
  "ios": {
    "exclude_files": "Sources/Public/MacOS/**/*",
    "frameworks": [
      "UIKit",
      "CoreGraphics",
      "QuartzCore"
    ]
  },
  "tvos": {
    "exclude_files": "Sources/Public/MacOS/**/*",
    "frameworks": [
      "UIKit",
      "CoreGraphics",
      "QuartzCore"
    ]
  },
  "osx": {
    "exclude_files": "Sources/Public/iOS/**/*",
    "frameworks": [
      "AppKit",
      "CoreGraphics",
      "QuartzCore"
    ]
  },
  "weak_frameworks": [
    "SwiftUI",
    "Combine"
  ],
  "module_name": "Lottie",
  "swift_version": "5.9"
}
